def _odstran_diakritiku(text: str) -> str:
    """Očistí text od diakritiky, emoji symbolov a normalizuje ho na alfanumerické malé písmená."""
    if not text:
        return ""
    nfkd = unicodedata.normalize('NFKD', str(text))
    # 🛡️ DEFENSIVE: Odfiltruje diakritiku aj ikony/emoji (ponechá iba bežné písmená, čísla a medzery)
    return "".join(c for c in nfkd if not unicodedata.combining(c) and (c.isalnum() or c.isspace())).lower().strip()

def _klasifikuj_externy_subjekt(typ_pomeru: str, rola_pouzivatela: str) -> tuple[bool, bool]:
    """
    Data-driven detekcia Súkromnej osoby (SukromnaOsoba) a B2B zákazníka (Zakaznik)
    využívajúca priamo metadáta z dátových modelov bez reťazcového hardkódu.
    Vracia dvojicu (is_sukromna_osoba, is_b2b).
    """
    from .models import SukromnaOsoba, Zakaznik, Zamestnanec

    typ_norm = _odstran_diakritiku(typ_pomeru)
    rola_norm = _odstran_diakritiku(rola_pouzivatela)

    # 🛡️ B2B FIREWALL SHIELD: Ak je používateľ evidovaný pod typom pomeru zamestnanca (IN, EX, BR, KO alebo jeho názov),
    # NIKDY nesmie byť klasifikovaný ako externý klient ani súkromná osoba, aj keby mal v role text 'B2B'.
    zamestnanecke_hodnoty = {
        _odstran_diakritiku(val)
        for code, label in Zamestnanec.POMER_CHOICES
        for val in (code, label)
        if val
    }
    if typ_norm in zamestnanecke_hodnoty:
        return False, False

    # 1. Detekcia súkromnej osoby podľa modelu SukromnaOsoba (očistené od emoji "👤 ")
    so_norm = _odstran_diakritiku(str(SukromnaOsoba._meta.verbose_name))
    is_so = (
        typ_norm in {'so', SukromnaOsoba.__name__.lower()} or
        (bool(so_norm) and (so_norm in typ_norm or so_norm in rola_norm))
    )
    if is_so:
        return True, False

    # 2. Detekcia B2B zákazníka podľa modelu Zakaznik (očistené od emoji "🏢 ")
    zakaznik_norm = _odstran_diakritiku(str(Zakaznik._meta.verbose_name))
    is_b2b = (
        typ_norm in {'b2b', 'zakaznik', Zakaznik.__name__.lower()} or
        rola_norm in {'b2b', 'zakaznik'} or
        (bool(zakaznik_norm) and (zakaznik_norm in typ_norm or zakaznik_norm in rola_norm)) or
        'b2b' in typ_norm or
        'b2b' in rola_norm
    )
    return False, is_b2b

